<script setup>
import { computed } from 'vue'
import { challengeReport, CHALLENGE_KINDS } from '../endfield-challenges.js'
import { displayValue as display, rows } from '../endfield-reports.js'
import { displayBeijing } from '../time.js'
import SummaryMetrics from './SummaryMetrics.vue'
import EndfieldChallengeGroups from './EndfieldChallengeGroups.vue'
const props = defineProps({ value: Object, kind: { type: String, default: 'war' }, busy: Boolean, error: String })
const emit = defineEmits(['select-kind', 'reload'])
const report = computed(() => challengeReport(props.value, props.kind))
const label = computed(() => CHALLENGE_KINDS.find(([id]) => id === props.kind)?.[1] || '挑战')
const errorText = computed(() => props.error || (typeof props.value?.error === 'string' ? props.value.error : ''))
const time = value => typeof value !== 'string' || !value ? '未知' : displayBeijing(value)
const pass = value => value === true ? '已通关' : value === false ? '未通关' : '状态未知'
const metrics = computed(() => [{label:'本次返回记录',value:report.value.summary?.listed_count}, ...(props.kind === 'crisis' ? [{label:'来源历史最高值',value:report.value.summary?.highest},{label:'来源挑战次数',value:report.value.summary?.challenge_count}] : [])])
</script>
<template>
  <div class="endfield-challenges">
    <section class="challenge-report"><header class="report-heading"><div><p class="kicker">FIELD OPERATIONS / CHALLENGE REPORT</p><h2>挑战记录</h2></div><button type="button" class="ui-button" :disabled="busy" @click="emit('reload')">{{ busy ? '读取中…' : `重新读取${label}` }}</button></header>
      <nav class="challenge-tabs" aria-label="挑战类型"><button v-for="[id,name] in CHALLENGE_KINDS" :key="id" type="button" :aria-pressed="kind===id" @click="emit('select-kind',id)">{{ name }}</button></nav>
      <div class="challenge-status"><span>{{ label }}抓取于 {{ time(report.fetched_at) }}（北京时间）</span><span v-if="report.stale && report.available" class="badge badge-stale">已有资料待更新</span></div>
      <p v-if="report.supported === false" class="challenge-empty">当前账号暂不支持{{ label }}挑战。</p>
      <template v-else>
        <p v-if="busy" class="challenge-note" role="status">正在读取{{ label }}记录<template v-if="report.available">，保留当前资料</template>…</p>
        <p v-if="errorText" class="challenge-error" role="alert">{{ errorText }}<span>{{ report.available ? '正在显示上次成功资料，抓取时间保持不变。' : '尚无可显示的已采集资料。' }}</span></p>
        <template v-if="report.available"><SummaryMetrics compact :metrics="metrics" /><p class="challenge-note coverage">仅展示本次接口返回的赛季与记录，不代表完整历史；没有来源上限时不计算完成率。</p></template>
        <p v-else-if="!busy && !errorText" class="challenge-empty">尚未采集{{ label }}记录，请重新读取。</p>
      </template>
    </section>
    <template v-if="report.available && report.supported !== false">
      <p v-if="!report.records.length" class="challenge-report challenge-empty">本次返回没有{{ label }}记录；不能据此判断所有挑战均已完成或尚未参与。</p>
      <details v-for="(record,index) in report.records" :key="record.id ?? index" class="challenge-report challenge-record" :open="index===0"><summary><div><p class="kicker">{{ kind==='war'?'SEASON':kind==='monument'?'OPERATION':'RECORD' }} {{ String(index+1).padStart(2,'0') }}</p><h3>{{ record.name || (record.id != null ? `记录 ${record.id}` : `挑战记录 ${index+1}`) }}</h3></div><span v-if="kind==='war'" class="record-result">{{ display(record.stars) }} 星</span><span v-else-if="kind==='crisis'" class="record-result">{{ display(record.result) }}</span><span class="record-toggle" aria-hidden="true">⌄</span></summary><div class="record-body">
        <p v-if="record.start_at || record.end_at" class="challenge-note period">{{ time(record.start_at) }} — {{ time(record.end_at) }}</p>
        <template v-if="kind==='war'"><p v-if="!rows(record.weeks).length" class="challenge-note">尚无轮换明细。</p><article v-for="(week,weekIndex) in rows(record.weeks)" :key="week.id ?? weekIndex" class="challenge-week"><header><div><p class="kicker">ROTATION {{ String(weekIndex+1).padStart(2,'0') }}</p><h4>{{ week.name || `轮换 ${weekIndex+1}` }}</h4></div><span>{{ display(week.stars) }} 星</span></header><EndfieldChallengeGroups :groups="week.groups" /></article></template>
        <EndfieldChallengeGroups v-else-if="kind==='monument'" :groups="record.groups" />
        <p v-else class="crisis-result">通关状态 <strong>{{ pass(record.passed) }}</strong></p>
      </div></details>
      <section v-if="kind==='war' && rows(report.honors).length" class="challenge-report"><header class="report-heading"><div><p class="kicker">HONORS / OBSERVED RECORDS</p><h3>已有荣誉</h3></div><span class="challenge-note">{{ report.honors.length }} 条</span></header><ul class="challenge-honors"><li v-for="(honor,index) in report.honors" :key="index"><div><strong>{{ honor.name || '未命名荣誉' }}</strong><p>首次通关 {{ time(honor.first_pass_at) }}</p></div><span>{{ display(honor.stars) }} 星</span></li></ul></section>
    </template>
  </div>
</template>
<style scoped>
.endfield-challenges{--accent:var(--game-endfield);--accent-soft:color-mix(in srgb,var(--game-endfield) 12%,var(--card-bg));--accent-hover:var(--game-endfield);--accent-strong:var(--game-endfield);display:grid;gap:16px;min-width:0;--challenge-cyan:#79c9d1}:global([data-theme="light"]) .endfield-challenges{--challenge-cyan:#147c88}.challenge-report{border:1px solid var(--border);border-top:2px solid color-mix(in srgb,var(--game-endfield) 65%,var(--border));background:var(--card-bg);padding:22px;min-width:0}.report-heading{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;padding-bottom:16px;border-bottom:1px solid var(--border);margin-bottom:18px}.kicker{font-family:var(--font-mono);font-size:10px;letter-spacing:.13em;color:var(--text-muted);margin-bottom:7px}.report-heading h2{font-size:21px}.report-heading h3{font-size:17px}.ui-button{border-radius:0}.challenge-tabs{display:flex;border-bottom:1px solid var(--border);margin-bottom:14px}.challenge-tabs button{flex:1;padding:12px;border:0;border-bottom:2px solid transparent;background:transparent;font-size:13px;color:var(--text-muted);min-height:44px}.challenge-tabs button[aria-pressed=true]{border-bottom-color:var(--game-endfield);color:var(--game-endfield);background:var(--accent-soft)}.challenge-status{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:12px 0;color:var(--text-muted);font-size:11px;line-height:1.7}.challenge-note{font-size:12px;color:var(--text-muted);line-height:1.8}.coverage{margin-top:14px}.challenge-empty{font-size:13px;color:var(--text-muted);line-height:1.8}.challenge-error{padding:12px;border-left:2px solid var(--danger);background:var(--danger-bg);color:var(--danger);font-size:12px;line-height:1.8;overflow-wrap:anywhere;margin-top:14px}.challenge-error>span{display:block;color:var(--text-muted)}.challenge-record{padding:0}.challenge-record>summary{display:flex;gap:12px;align-items:center;padding:20px 22px;cursor:pointer;list-style:none}.challenge-record>summary::-webkit-details-marker{display:none}.challenge-record>summary>div{min-width:0;flex:1}.challenge-record h3{font-size:17px;line-height:1.5;overflow-wrap:anywhere}.record-result{font-family:var(--font-mono);font-size:22px;color:var(--game-endfield);overflow-wrap:anywhere;max-width:45%}.record-toggle{font-size:18px;color:var(--text-muted);transform:rotate(-90deg)}details[open]>.record-toggle,details[open]>summary>.record-toggle{transform:none}.record-body{padding:0 22px 22px}.period{margin-bottom:16px}.challenge-week{padding-top:16px;margin-top:16px;border-top:1px solid var(--border)}.challenge-week>header{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:14px}.challenge-week h4{font-size:14px}.challenge-week>header>span{font-family:var(--font-mono);color:var(--challenge-cyan);font-size:16px}.challenge-honors li{display:flex;justify-content:space-between;gap:14px;padding:14px 0;border-bottom:1px solid var(--border)}.challenge-honors strong{font-size:13px;font-weight:500}.challenge-honors p{font-size:11px;color:var(--text-muted);margin-top:7px}.challenge-honors li>span{font-family:var(--font-mono);font-size:15px;color:var(--challenge-cyan);white-space:nowrap}.crisis-result{display:flex;justify-content:space-between;border-top:1px solid var(--border);padding-top:16px;font-size:13px;color:var(--text-muted)}.crisis-result strong{font-weight:500;color:var(--text)}.endfield-challenges :deep(.summary-metric),.endfield-challenges :deep(.metric-symbol){border-radius:0}.endfield-challenges :deep(.metric-copy>strong){font-family:var(--font-mono);font-weight:500}@media(max-width:600px){.challenge-report{padding:16px}.report-heading h2{font-size:19px}.challenge-record{padding:0}.challenge-record>summary{padding:16px}.challenge-record h3{font-size:15px}.record-body{padding:0 16px 16px}.record-result{font-size:18px}.challenge-honors li{gap:10px}}
</style>
